function SearchBox() {
  const inputRef = useRef(null);

  useEffect(() => {
    inputRef.current.focus();
  }, []);

  return <input ref={inputRef} />;
}

function Measured() {
  const [height, setHeight] = useState(0);

  const measure = useCallback((node) => {
    if (node) setHeight(node.getBoundingClientRect().height);
  }, []);

  return <div ref={measure}>Content</div>;
}

function Rows({ items }) {
  const rowRefs = useRef(new Map());

  function scrollTo(id) {
    rowRefs.current.get(id)?.scrollIntoView({ behavior: "smooth" });
  }

  return items.map((item) => (
    <li key={item.id} ref={(node) => {
      if (node) rowRefs.current.set(item.id, node);
      else rowRefs.current.delete(item.id);
    }}>
      {item.name}
    </li>
  ));
}

function usePrevious(value) {
  const ref = useRef(undefined);

  useEffect(() => {
    ref.current = value;
  }, [value]);

  return ref.current;   // the value from the previous render
}

function Price({ amount }) {
  const previous = usePrevious(amount);
  const hasRisen = previous !== undefined && amount > previous;

  return <span className={hasRisen ? "up" : ""}>{amount}</span>;
}

function useInterval(callback, delay) {
  const savedCallback = useRef(callback);

  useEffect(() => {
    savedCallback.current = callback;
  }, [callback]);

  useEffect(() => {
    const id = setInterval(() => savedCallback.current(), delay);
    return () => clearInterval(id);
  }, [delay]);   // the interval only resets when the delay changes
}
